// enum: emits real runtime JS, numeric values are opaque in logs
enum Status { Idle, Loading, Success, Error }

// as-const alternative: zero runtime cost, self-describing values
const Status = { Idle: 'idle', Loading: 'loading', Success: 'success', Error: 'error' } as const;
type Status = typeof Status[keyof typeof Status];
// 'idle' | 'loading' | 'success' | 'error'

type ElementType<T> = T extends readonly (infer U)[] ? U : T;

type A = ElementType<string[]>;   // string
type B = ElementType<number>;     // number (T doesn't match the array branch)

type UnwrapPromise<T> = T extends Promise<infer V> ? V : T;
type C = UnwrapPromise<Promise<Topic>>; // Topic

abstract class ContentRenderer {
  abstract render(block: ContentBlock): string;

  renderAll(blocks: ContentBlock[]): string {
    return blocks.map(b => this.render(b)).join('\n'); // shared implementation
  }
}

class HtmlRenderer extends ContentRenderer {
  render(block: ContentBlock): string { /* concrete implementation */ return ''; }
}

function parseTags(input: string): string[];
function parseTags(input: string[]): string;
function parseTags(input: string | string[]): string | string[] {
  return Array.isArray(input) ? input.join(',') : input.split(',');
}

parseTags('a,b,c');       // string[]
parseTags(['a', 'b']);    // string
